-- Urban Redevelopment Authority, Master Plan 2019 Region Boundary (No Sea).
-- https://data.gov.sg/datasets/d_bf4d24df9129d5a8ff8cf82e20959ee0/view
-- Singapore Open Data Licence v1.0. Source GeoJSON SHA256: 2ac87b6da63c39d6311c7bc018aafddbffcfa18fd8faed09243207c9b502627d
-- Coordinates use microdegrees so PostgreSQL geometric tolerance remains below source precision.
-- Each row retains one polygon's exterior and interior rings in longitude/latitude order.
create schema recycling_geo;
revoke all on schema recycling_geo from public, anon, authenticated;
create table recycling_geo.boundaries (
    region text not null,
    shell polygon not null,
    holes polygon[] not null,
    bounds box generated always as (box(shell)) stored
);


create function recycling_geo.region_at(lon double precision, lat double precision)
returns text language sql stable strict set search_path = '' as $$
    select b.region from recycling_geo.boundaries b
    where b.bounds @> point(lon*1000000,lat*1000000) and b.shell @> point(lon*1000000,lat*1000000)
      and not exists (select from unnest(b.holes) hole where hole @> point(lon*1000000,lat*1000000))
    order by b.region collate "C" limit 1
$$;

create function recycling_geo.assign_region() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
    if tg_op = 'UPDATE' then
        if (new.longitude,new.latitude) = (old.longitude,old.latitude) then
            if nullif(btrim(new.region),'') is null and nullif(btrim(old.region),'') is not null then
                new.region := old.region;
            end if;
        elsif new.region is not distinct from old.region
              and old.region = recycling_geo.region_at(old.longitude,old.latitude) then
            new.region := null;
        end if;
    end if;
    if nullif(btrim(new.region),'') is null then
        new.region := recycling_geo.region_at(new.longitude,new.latitude);
    end if;
    return new;
end
$$;
revoke all on all functions in schema recycling_geo from public, anon, authenticated;

create trigger assign_recycling_point_region before insert or update of region,longitude,latitude
on public.recycling_points for each row execute function recycling_geo.assign_region();

update public.recycling_points set region = null where nullif(btrim(region),'') is null;

select p.id,b.id from public.profiles p cross join lateral public.badge_progress(p.id) b
where b.criterion='regions' and b.progress>=b.target and b.earned_at is null
on conflict do nothing;
